WITH scored AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, AVG(amount) OVER (PARTITION BY txn_type ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS amount_avg_90d, MAX(amount) OVER w_recent AS amount_max_7d, AVG(amount) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS amount_avg_5, FIRST_VALUE(merchant, TRUE) OVER (ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_merchant, COUNT(amount) OVER (PARTITION BY merchant) AS merchant_count_amount FROM transactions WINDOW w_recent AS (PARTITION BY txn_type ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW)) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, PERCENTILE_APPROX(amount_max_7d, ARRAY(0.25, 0.5, 0.75)) AS amount_max_7d_quartiles, COUNT_IF(merchant = 'Lazada') AS lazada_events, COUNT_IF(txn_type = 'CREDIT') AS credit_events FROM scored GROUP BY activity_month HAVING lazada_events > 1 ORDER BY lazada_events DESC NULLS LAST;
